import sys, docx
from docx.document import Document as _D
from docx.oxml.ns import qn
from docx.table import Table
from docx.text.paragraph import Paragraph
def iter_block_items(parent):
    body = parent.element.body
    for child in body.iterchildren():
        if child.tag == qn('w:p'):
            yield Paragraph(child, parent)
        elif child.tag == qn('w:tbl'):
            yield Table(child, parent)
d = docx.Document(sys.argv[1])
for b in iter_block_items(d):
    if isinstance(b, Paragraph):
        t = b.text
        if t.strip():
            st = b.style.name if b.style is not None else ''
            print(("[%s] " % st if st.startswith('Heading') else '') + t)
    else:
        print("<<TABLE>>")
        for r in b.rows:
            cells = []
            prev = None
            for c in r.cells:
                if c._tc is prev: continue
                prev = c._tc
                cells.append(c.text.replace('\n',' / '))
            print(" | ".join(cells))
        print("<<END TABLE>>")
# headers/footers
for s in d.sections:
    for p in s.header.paragraphs:
        if p.text.strip(): print("HEADER:", p.text)
    for p in s.footer.paragraphs:
        if p.text.strip(): print("FOOTER:", p.text)
