        DISABLE_WARNING_POP
        Int64 const hash(Tdb_tag & psatcache_mask);
        auto &cPsat(state.dataPsychCache->cached_Psat[hash]);

        if (cPsat.iTdb != Tdb_tag) {
            cPsat.iTdb = Tdb_tag;
            Tdb_tag <<= Grid_Shift;
