import math
import model as M, data as D, econ
from bins import make_bins
BINS, NOBS = make_bins()
DESIGN_WB = 80.0     # 1.0 % annual WB (75 F) + 5 F, UFC 3-410-01 2-4.2.4
RED_WB = 81.0        # 0.4 % annual WB (76 F) + 5 F, P100 5.1.3 + RFI-031
DB996 = 41.0
PEAKDAY_DB = 112.0

def B_factor(T):
    pts = D.B_POINTS
    if T <= pts[0][0]:
        return pts[0][1]
    for (t0, b0), (t1, b1) in zip(pts[:-1], pts[1:]):
        if t0 <= T <= t1:
            return b0 + (b1 - b0) * (T - t0) / (t1 - t0)
    return pts[-1][1]

def psi(coc, cwr_F):
    A = (math.log10(D.TDS_MU * coc) - 1) / 10
    B = B_factor(cwr_F)
    C = math.log10(D.CA_MU * coc) - 0.4
    Dd = math.log10(D.ALK_CIRC)
    phs = 9.30 + A + B - (C + Dd)
    pheq = 1.485 * math.log10(D.ALK_CIRC) + 4.54
    return 2 * phs - pheq

def max_coc(cwr_F):
    lo, hi = 1.0, 9.375
    if psi(hi, cwr_F) >= D.PSI_MIN:
        return hi
    for _ in range(100):
        mid = (lo + hi) / 2
        if psi(mid, cwr_F) >= D.PSI_MIN:
            lo = mid
        else:
            hi = mid
    return min(lo, 150.0 / D.SIO2_MU)

def simulate(d, bins=BINS):
    rows = [d.operate(b['wb'], b['db']) for b in bins]
    return rows

def evaluate(d, coc_margin=0.03, set_coc=True, evap='LOSS-FACTOR', want_rows=False):
    """Simulate a design; returns metrics, constraint checks and LCC."""
    out = {}
    dp = d.design_point(DESIGN_WB)
    out['dp'] = dp
    cmax = max_coc(dp['cwr_F'])
    out['coc_max'] = cmax
    if set_coc:
        d.coc = math.floor((cmax - coc_margin) * 100) / 100.0
    rows = simulate(d)
    hrs = [b['hours'] for b in BINS]
    kwh_ch = sum(r['ch_kw'] * h for r, h in zip(rows, hrs))
    kwh_fan = sum(r['fan_kw'] * h for r, h in zip(rows, hrs))
    kwh_pump = sum(r['pump_kw'] * h for r, h in zip(rows, hrs))
    kwh = kwh_ch + kwh_fan + kwh_pump
    peak = max(r['total_kw'] for r in rows)
    k = lambda key: sum(r[key] * h * 60 for r, h in zip(rows, hrs)) / 1000.0
    out.update(kwh=kwh, kwh_ch=kwh_ch, kwh_fan=kwh_fan, kwh_pump=kwh_pump, peak=peak,
               mu_sat=k('mu_sat'), bd_sat=k('bd_sat'), ev_sat=k('evap_sat'), drift_kgal=k('drift'),
               mu_lf=k('mu_lf'), bd_lf=k('bd_lf'), ev_lf=k('evap_lf'))
    # peak day
    pdr = d.operate(DESIGN_WB, PEAKDAY_DB, load_tons=d.plant['design_load'])
    out['pd'] = pdr
    sfx = 'sat' if evap == 'SATURATED-EXIT' else 'lf'
    out['pd_mu_gal'] = pdr['mu_' + sfx] * 1440
    out['pd_bd_gal'] = pdr['bd_' + sfx] * 1440
    out['mu_decl'] = out['mu_' + sfx]
    # redundancy
    rd = d.redundancy(RED_WB)
    out['rd'] = rd
    # checks
    ch = d.ch; m = d.m; N = d.N
    fails = []
    q1 = d.gpm / N
    if not (ch['qmin'] <= q1 <= ch['qmax']):
        fails.append('chiller flow %.0f' % q1)
    if d.cells % N != 0:
        fails.append('cells multiple')
    if m['snd'] > 102:
        fails.append('sound')
    for r, b in zip(rows, BINS):
        fc = r['flow'] / r['k']
        if not (D.YORK['wfrr_min'] - 1e-9 <= r['wfrr'] <= D.YORK['wfrr_max'] + 1e-9):
            fails.append('wfrr %.3f @%s/%s' % (r['wfrr'], b['wb'], b['db'])); break
        if not (m['gmin'] - 1e-9 <= fc <= m['gmax'] + 1e-9):
            fails.append('cellflow @%s' % b['wb']); break
        rng_c = r['range_F'] / 1.8; app_c = (r['cws_F'] - b['wb']) / 1.8
        if rng_c < D.YORK['tr_min'] or rng_c > D.YORK['tr_max']:
            fails.append('range %.2fF @%s/%s' % (r['range_F'], b['wb'], b['db'])); break
        if app_c < D.YORK['ta_min'] - 1e-9 or app_c > D.YORK['ta_max']:
            fails.append('approach %.2fF @%s/%s' % (r['cws_F'] - b['wb'], b['wb'], b['db'])); break
        if r['afr'] > D.MIN_AFR and r['wfrr'] / r['afr'] > D.YORK['lg_max']:
            fails.append('L/G'); break
        if r['cws_F'] > ch['ecwt_max_F'] + 1e-9:
            fails.append('cws>max @%s' % b['wb']); break
        if r['avail_tons'] < r['load'] - 1e-6:
            fails.append('capacity @%s/%s' % (b['wb'], b['db'])); break
    # design point validity
    if not (D.YORK['wfrr_min'] <= dp['wfrr'] <= D.YORK['wfrr_max']):
        fails.append('dp wfrr %.3f' % dp['wfrr'])
    if (dp['cws_F'] - DESIGN_WB) / 1.8 < D.YORK['ta_min']:
        fails.append('dp approach')
    if dp['avail_tons'] < d.plant['design_load']:
        fails.append('dp capacity')
    if rd is None:
        fails.append('no redundancy')
    else:
        fc = d.gpm / (d.cells - 1)
        if fc > m['gmax'] + 1e-9 or rd['wfrr'] > D.YORK['wfrr_max'] + 1e-9:
            fails.append('red cell flow %.0f' % fc)
        if rd['cws_F'] > ch['ecwt_max_F']:
            fails.append('red cws %.2f' % rd['cws_F'])
        if rd['red_cap_tons'] < d.plant['design_load']:
            fails.append('red capacity %.1f' % rd['red_cap_tons'])
    if d.coc > cmax + 0.01:
        fails.append('coc')
    if out['mu_decl'] > d.plant['alloc']:
        fails.append('allocation %.0f' % out['mu_decl'])
    if out['pd_mu_gal'] > d.plant['peakday']:
        fails.append('peakday %.0f' % out['pd_mu_gal'])
    if out['pd_bd_gal'] > d.plant['bdlimit']:
        fails.append('bdlimit %.0f' % out['pd_bd_gal'])
    if peak > d.plant['spare']:
        fails.append('electrical %.1f' % peak)
    if d.floor < ch['ecwt_min_F'] - 1e-9:
        fails.append('floor<min ECWT')
    out['fails'] = fails
    out['ok'] = not fails
    L = econ.lcc(d.model, d.cells, d.material, d.elim, d.premium, kwh, peak, out['mu_sat'], out['bd_sat'])
    out['lcc'] = L
    if want_rows:
        out['rows'] = rows
    return out

_basic_cache = {}
def basic_lcc(pname):
    if pname not in _basic_cache:
        b = D.BASIC
        d = M.Design(pname, b['model'], b['cells'], b['gpm'], b['floor'], b['offset'], b['coc'], b['elim'], b['material'], b['premium'])
        ev = evaluate(d, set_coc=False)
        _basic_cache[pname] = ev
    return _basic_cache[pname]

if __name__ == '__main__':
    for p in ('CUP', 'ANNEX', 'LAB'):
        ev = basic_lcc(p)
        L = ev['lcc']
        print(p, 'basic: kWh %.0f peak %.1f mu_sat %.0f bd_sat %.0f mu_lf %.0f LCC %.0f' % (ev['kwh'], ev['peak'], ev['mu_sat'], ev['bd_sat'], ev['mu_lf'], L['LCC_USD']), ev['fails'])
        print('    inv %.0f pvE %.0f pvW %.0f pvOM %.0f' % (L['Investment_USD'], L['PVEnergy_USD'], L['PVWater_USD'], L['PVOM_USD']))

"""Roof layout: place n identical cells in the M-401 Rev C equipment zone with VD-01 clearances,
S-401 framing zones (support within one zone, superimposed load <= allowable) and P100 intake separation."""
import math
import data as D

INTAKE_SEP = 25.0

def psf(model):
    m = D.MODELS[model]
    return m['opwt'] / (m['w'] * m['l'])

def columns(plant, model, cw, xmin, xmax, c):
    """Greedy left-to-right column positions (x-left) for column width cw."""
    p = D.PLANTS[plant]
    load = psf(model)
    cols = []
    x = xmin
    while x + cw <= xmax + 1e-9:
        # find framing zone containing [x, x+cw]
        placed = False
        for (fx0, fy0, fx1, fy1, allow, name) in p['framing']:
            if fx0 - 1e-9 <= x and x + cw <= fx1 + 1e-9 and load <= allow + 1e-9:
                cols.append((x, name, allow))
                x = x + cw + c
                placed = True
                break
        if not placed:
            # move x to the next framing boundary to the right that is > x
            nxt = [fx0 for (fx0, fy0, fx1, fy1, allow, name) in p['framing'] if fx0 > x + 1e-9 and load <= allow + 1e-9]
            if not nxt:
                break
            x = min(nxt)
    return cols

def place(plant, model, n):
    """Return list of rectangles (x0,y0,x1,y1,zone_name,allow) for n cells, or None."""
    p = D.PLANTS[plant]
    m = D.MODELS[model]
    c = m['clr']
    zx0, zy0, zx1, zy1 = p['zone']
    best = None
    for (cw, chh) in ((m['w'], m['l']), (m['l'], m['w'])):
        xmin, xmax = zx0 + c, zx1 - c
        ymin, ymax = zy0 + c, zy1 - c
        cols = columns(plant, model, cw, xmin, xmax, c)
        nrows = int(math.floor((ymax - ymin + c) / (chh + c) + 1e-9))
        cap = len(cols) * nrows
        if cap >= n and nrows >= 1:
            rects = []
            # fill column-major, rows bottom-up; centre rows vertically for symmetry
            used_h = nrows * chh + (nrows - 1) * c
            y_start = ymin + (ymax - ymin - used_h) / 2.0 if nrows > 0 else ymin
            for (x, name, allow) in cols:
                for j in range(nrows):
                    if len(rects) >= n:
                        break
                    y = y_start + j * (chh + c)
                    rects.append((x, y, x + cw, y + chh, name, allow))
            # intake separation check
            okint = all(rect_point_dist(r, pt) >= INTAKE_SEP for r in rects for pt in p['intakes'])
            if okint:
                if best is None:
                    best = rects
    return best

def rect_point_dist(r, pt):
    x0, y0, x1, y1 = r[:4]
    dx = max(x0 - pt[0], 0, pt[0] - x1)
    dy = max(y0 - pt[1], 0, pt[1] - y1)
    return math.hypot(dx, dy)

def max_cells(plant, model):
    n = 0
    while place(plant, model, n + 1) is not None:
        n += 1
        if n > 40:
            break
    return n

if __name__ == '__main__':
    for p in D.PLANTS:
