FINAL_LAYOUTS = {
 ('CUP', 'CTX-0600-S', 4):   [(14.5, 20.0, 24.5, 40.0), (31.0, 20.0, 41.0, 40.0), (47.5, 20.0, 57.5, 40.0), (64.0, 20.0, 74.0, 40.0)],
