 ('LAB', 'CTX-0900-H', 3):   [(19.0, 419.0, 31.0, 451.0), (37.5, 419.0, 49.5, 451.0), (56.0, 419.0, 68.0, 451.0)],
}

def final_layout(plant, model, n):
    key = (plant, model, n)
    if key not in FINAL_LAYOUTS:
        return place(plant, model, n)
    p = D.PLANTS[plant]; m = D.MODELS[model]; c = m['clr']
    zx0, zy0, zx1, zy1 = p['zone']
    load = psf(model)
    out = []
    for (x0, y0, x1, y1) in FINAL_LAYOUTS[key]:
        assert abs((x1 - x0) * (y1 - y0) - m['w'] * m['l']) < 1e-9
        assert x0 >= zx0 + c and y0 >= zy0 + c and x1 <= zx1 - c and y1 <= zy1 - c, 'zone clearance'
        fz = [f for f in p['framing'] if f[0] <= x0 and x1 <= f[2] and f[1] <= y0 and y1 <= f[3]]
        assert fz and load <= fz[0][4], 'framing'
        for pt in p['intakes']:
            assert rect_point_dist((x0, y0, x1, y1), pt) >= INTAKE_SEP
        out.append((x0, y0, x1, y1, fz[0][5], fz[0][4]))
    for i in range(len(out)):
        for j in range(i + 1, len(out)):
            a, b = out[i], out[j]
            dx = max(b[0] - a[2], a[0] - b[2], 0); dy = max(b[1] - a[3], a[1] - b[3], 0)
            assert math.hypot(dx, dy) >= c, 'cell spacing'
    return out
